// Scriptable number-part audio test.
// Self-contained version with embedded pre-generated digit/unit audio.

const audioSources = {"0":"data:audio/mp4;base64,","1":"data:audio/mp4;base64,","10":"data:audio/mp4;base64,","100":"data:audio/mp4;base64,","1000":"data:audio/mp4;base64,","2":"data:audio/mp4;base64,","3":"data:audio/mp4;base64,","4":"data:audio/mp4;base64,","5":"data:audio/mp4;base64,","6":"data:audio/mp4;base64,","7":"data:audio/mp4;base64,","8":"data:audio/mp4;base64,","9":"data:audio/mp4;base64,","hour":"data:audio/mp4;base64,","minute":"data:audio/mp4;base64,"};

const html = `<!doctype html>
<html lang="ja">
<head>
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<style>
  :root { color-scheme: dark; font-family: -apple-system, BlinkMacSystemFont, sans-serif; }
  body { margin: 0; padding: 18px; background: #111; color: #f5f5f7; }
  h1 { font-size: 22px; margin: 0 0 14px; }
  .card { border: 1px solid #333; border-radius: 10px; padding: 14px; margin: 12px 0; background: #1c1c1e; }
  button { width: 100%; border: 0; border-radius: 8px; padding: 13px; margin: 6px 0; background: #0a84ff; color: white; font-size: 16px; }
  button.secondary { background: #3a3a3c; }
  label { display: block; margin: 10px 0 4px; color: #c7c7cc; font-size: 13px; }
  input, select { box-sizing: border-box; width: 100%; border: 1px solid #3a3a3c; border-radius: 8px; padding: 10px; background: #111; color: #f5f5f7; font-size: 16px; }
  .row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
  pre { white-space: pre-wrap; word-break: break-word; max-height: 300px; overflow: auto; background: #000; border-radius: 8px; padding: 10px; color: #d1d1d6; }
</style>
</head>
<body>
<h1>数字パーツ読み上げテスト</h1>
<div class="card">
  <label>読み上げ粒度</label>
  <select id="mode">
    <option value="second">秒だけ</option>
    <option value="minute">分+秒</option>
    <option value="hour">時+分+秒</option>
  </select>
  <div class="row">
    <div><label>時</label><input id="hour" type="number" min="0" max="23" value="12"></div>
    <div><label>分</label><input id="minute" type="number" min="0" max="59" value="34"></div>
  </div>
  <div class="row">
    <div><label>秒</label><input id="second" type="number" min="0" max="59" value="56"></div>
    <div><label>目標秒</label><input id="target" type="number" min="0.2" max="3" step="0.05" value="0.9"></div>
  </div>
  <div class="row">
    <div><label>最大rate</label><input id="maxRate" type="number" min="1" max="16" step="0.5" value="6"></div>
    <div><label>連続間隔ms</label><input id="period" type="number" min="100" step="100" value="1000"></div>
  </div>
</div>
<div class="card">
  <button id="play">単発再生</button>
  <button id="series">1秒ごとに10回</button>
  <button id="stop" class="secondary">停止</button>
</div>
<div class="card"><pre id="log"></pre></div>
<script>
const SOURCES = ${JSON.stringify(audioSources)};
const cache = {};
let stopped = false;
let timer = null;
function log(msg) {
  const t = new Date().toLocaleTimeString("ja-JP", { hour12: false }) + "." + String(Date.now() % 1000).padStart(3, "0");
  document.getElementById("log").textContent = "[" + t + "] " + msg + "\\n" + document.getElementById("log").textContent;
}
function num(id) { return Math.max(0, parseInt(document.getElementById(id).value, 10) || 0); }
function getAudio(name) {
  if (!cache[name]) {
    const a = new Audio(SOURCES[name]);
    a.preload = "auto";
    cache[name] = a;
  }
  return cache[name];
}
function cloneAudio(name) {
  const a = getAudio(name);
  const b = new Audio(a.src);
  b.preload = "auto";
  return b;
}
function composeNumber(n) {
  n = Math.max(0, Math.min(9999, Math.floor(n)));
  if (n === 0) return ["0"];
  const parts = [];
  const th = Math.floor(n / 1000);
  const hu = Math.floor((n % 1000) / 100);
  const te = Math.floor((n % 100) / 10);
  const on = n % 10;
  if (th > 0) { if (th > 1) parts.push(String(th)); parts.push("1000"); }
  if (hu > 0) { if (hu > 1) parts.push(String(hu)); parts.push("100"); }
  if (te > 0) { if (te > 1) parts.push(String(te)); parts.push("10"); }
  if (on > 0) parts.push(String(on));
  return parts;
}
function composeCurrent() {
  const mode = document.getElementById("mode").value;
  const h = Math.min(23, num("hour"));
  const m = Math.min(59, num("minute"));
  const s = Math.min(59, num("second"));
  if (mode === "second") return composeNumber(s);
  if (mode === "minute") return composeNumber(m).concat(["minute"]).concat(composeNumber(s));
  return composeNumber(h).concat(["hour"]).concat(composeNumber(m)).concat(["minute"]).concat(composeNumber(s));
}
async function loadDurations(parts) {
  await Promise.all(parts.map(function(name) {
    return new Promise(function(resolve) {
      const a = getAudio(name);
      if (Number.isFinite(a.duration) && a.duration > 0) return resolve();
      a.onloadedmetadata = function() { resolve(); };
      a.onerror = function() { resolve(); };
      a.load();
    });
  }));
}
async function playParts(parts) {
  stopped = false;
  await loadDurations(parts);
  const total = parts.reduce(function(sum, name) {
    const d = getAudio(name).duration;
    return sum + (Number.isFinite(d) ? d : 0);
  }, 0);
  const target = Math.max(0.2, Number(document.getElementById("target").value) || 0.9);
  const maxRate = Math.max(1, Number(document.getElementById("maxRate").value) || 6);
  const rate = Math.min(maxRate, Math.max(1, total / target));
  log("parts=" + parts.join(" ") + " natural=" + total.toFixed(3) + "s rate=" + rate.toFixed(2));
  for (const name of parts) {
    if (stopped) return;
    await new Promise(function(resolve) {
      const a = cloneAudio(name);
      a.playbackRate = rate;
      a.onended = resolve;
      a.onerror = resolve;
      a.play().catch(function(err) { log("play error " + err); resolve(); });
    });
  }
}
function stopAll() {
  stopped = true;
  if (timer) clearInterval(timer);
  timer = null;
  Object.keys(cache).forEach(function(name) { try { cache[name].pause(); cache[name].currentTime = 0; } catch (_) {} });
  log("stopped");
}
document.getElementById("play").onclick = function() { playParts(composeCurrent()); };
document.getElementById("series").onclick = function() {
  stopAll();
  let i = 0;
  const period = Math.max(100, Number(document.getElementById("period").value) || 1000);
  function tick() {
    i += 1;
    document.getElementById("second").value = String((num("second") + 1) % 60);
    playParts(composeCurrent());
    if (i >= 10) { clearInterval(timer); timer = null; log("series scheduled done"); }
  }
  tick();
  timer = setInterval(tick, period);
};
document.getElementById("stop").onclick = stopAll;
log("ready");
</script>
</body>
</html>`;

const web = new WebView();
await web.loadHTML(html);
await web.present();

